import os, sqlite3, json
from datetime import datetime
from flask import Flask, g, jsonify, request, render_template_string
app=Flask(__name__)
DB=os.environ.get("DATABASE_PATH","buildingsupplydesk.db")
def db():
 if "db" not in g:
  g.db=sqlite3.connect(DB); g.db.row_factory=sqlite3.Row
 return g.db
@app.teardown_appcontext
def close_db(e):
 c=g.pop("db",None)
 if c:c.close()
def init_db():
 c=sqlite3.connect(DB)
 c.executescript("""CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,sku TEXT UNIQUE,name TEXT,category TEXT,description TEXT,unit TEXT,price REAL,trade REAL,stock INTEGER,branch TEXT); CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,customer TEXT,email TEXT,fulfillment TEXT,delivery_date TEXT,items TEXT,total REAL,status TEXT,created TEXT); CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY,customer TEXT,email TEXT,project TEXT,materials TEXT,status TEXT,created TEXT);""")
 if c.execute("SELECT COUNT(*) FROM products").fetchone()[0]==0:
  rows=[
  ("LBR-2X4-8","2×4 SPF Stud — 8 ft","Lumber","Kiln-dried framing lumber.","piece",4.28,3.82,860,"Chatsworth"),
  ("LBR-PLY-OSB","7/16 in OSB Sheathing — 4×8","Lumber","Structural wall and roof sheathing.","sheet",18.95,16.75,214,"Chatsworth"),
  ("DRY-12-4X8","1/2 in Drywall — 4×8","Drywall & Insulation","Lightweight gypsum wallboard.","sheet",15.40,13.90,175,"Chatsworth"),
  ("RFG-ARCH-30","Architectural Shingles — 30 yr","Roofing","Laminated asphalt shingles.","bundle",39.50,35.75,92,"Chatsworth"),
  ("WIN-VIN-3050","Vinyl Window — 3050","Windows & Doors","White vinyl dual-pane low-E window.","each",189,174,18,"Chatsworth"),
  ("DR-EXT-3068","Exterior Prehung Door — 3068","Windows & Doors","Steel insulated exterior door.","each",329,299,12,"Chatsworth"),
  ("INS-R13-15","R-13 Fiberglass Batt Insulation","Drywall & Insulation","Kraft-faced fiberglass insulation.","bag",68,61.50,47,"Chatsworth"),
  ("CON-80-50","80 lb Concrete Mix","Concrete & Masonry","General-purpose concrete mix.","bag",7.85,7.10,340,"Chatsworth"),
  ("HWD-SCR-3","3 in Exterior Deck Screws — 5 lb","Hardware & Fasteners","Coated exterior construction screws.","box",29.95,26.50,64,"Chatsworth"),
  ("TRM-1X4-12","1×4 Primed Pine Trim — 12 ft","Lumber","Finger-jointed primed trim board.","piece",12.80,11.40,120,"Chatsworth"),
  ("FLA-ICE-2SQ","Ice & Water Shield — 2 sq roll","Roofing","Self-adhered roofing underlayment.","roll",89,81,28,"Chatsworth"),
  ("WIN-FLASH-50","Window Flashing Tape — 4 in × 50 ft","Windows & Doors","Self-adhering flashing tape.","roll",24.50,21.75,53,"Chatsworth")]
  c.executemany("INSERT INTO products(sku,name,category,description,unit,price,trade,stock,branch) VALUES(?,?,?,?,?,?,?,?,?)",rows)
 c.commit();c.close()
@app.get("/api/products")
def products():return jsonify([dict(x) for x in db().execute("SELECT * FROM products ORDER BY category,name")])
@app.get("/api/orders")
def orders():return jsonify([dict(x) for x in db().execute("SELECT * FROM orders ORDER BY id DESC")])
@app.get("/api/quotes")
def quotes():return jsonify([dict(x) for x in db().execute("SELECT * FROM quotes ORDER BY id DESC")])
@app.post("/api/orders")
def create_order():
 d=request.get_json(force=True)
 if not d.get("customer") or not d.get("email") or not d.get("items"):return jsonify(error="Customer, email and items are required"),400
 total=0
 for i in d["items"]:
  p=db().execute("SELECT price,stock FROM products WHERE id=?",(i.get("id"),)).fetchone()
  if not p or int(i.get("qty",0))<1:return jsonify(error="Invalid item or quantity"),400
  if int(i["qty"])>p["stock"]:return jsonify(error="Requested quantity exceeds sample stock"),400
  total+=p["price"]*int(i["qty"])
 cur=db().execute("INSERT INTO orders(customer,email,fulfillment,delivery_date,items,total,status,created) VALUES(?,?,?,?,?,?,?,?)",(d["customer"],d["email"],d.get("fulfillment","Branch pickup"),d.get("date",""),json.dumps(d["items"]),total,"New",datetime.utcnow().isoformat()))
 db().commit();return jsonify(id=cur.lastrowid,total=total),201
@app.post("/api/quotes")
def create_quote():
 d=request.get_json(force=True)
 if not d.get("customer") or not d.get("email") or not d.get("materials"):return jsonify(error="Customer, email and material list are required"),400
 cur=db().execute("INSERT INTO quotes(customer,email,project,materials,status,created) VALUES(?,?,?,?,?,?)",(d["customer"],d["email"],d.get("project",""),d["materials"],"New",datetime.utcnow().isoformat()))
 db().commit();return jsonify(id=cur.lastrowid),201
